def amp_phase_PhenomD_Horizon(m1,m2,chi1,chi2,DL,tc,phic,iota,f_ini=None,f_final=None,delta_f=None,Mf2amp=0.014,Mf2phase=0.018,amp_corr=False,phase_corr=True):
    
    q = m1/m2
    eta = urel.eta_of_q(q)
    M = (m1+m2)*urel.MTsun
    DLt = DL * urel.time_fac/urel.strain_fac

    chiPN = urel.chi_PN(m1,m2,chi1,chi2)
    chihat = urel.chi_hat(m1,m2,chi1,chi2)
    
    if delta_f is None: raise Exception('Specify delta_f')
    if f_ini is None: raise Exception('Specify f_ini')

    if f_final is None:
        hpd, hcd = waveform.get_fd_waveform(approximant='IMRPhenomD',
                             mass1=m1, mass2=m2, spin1z=chi1, spin2z=chi2, distance = DL, 
                                  delta_f=delta_f, f_lower = f_ini, f_final = 0)
    else:
        hpd, hcd = waveform.get_fd_waveform(approximant='IMRPhenomD',
                             mass1=m1, mass2=m2, spin1z=chi1, spin2z=chi2, distance = DL, 
                                  delta_f=delta_f, f_lower = f_ini, f_final = f_final)
    
    indexini =np.where(hpd.sample_frequencies>f_ini)[0][0]
    
    hplusD = hpd[indexini:]
    fpatch = np.zeros(indexini)
    f = hpd.sample_frequencies[indexini:]
    
    amphtf2,phase_htf2 = insp.HTF2(f,m1,m2,chi1,chi2,DL,tc,phic,iota,amp_phase_only=True,same_as_PhenomD=0)
    ampTH = insp.ampTH(f,m1,m2,chi1,chi2,DL)
    
    ## amplitude model ------------------
    
    ampd = np.abs(hplusD)
    ampdinterp = interp1d(f,ampd)
    
    augamp = np.zeros_like(f)
    amp_int = np.zeros_like(f)
    
    f0amp = Mf2amp/M
    
    if amp_corr==False: imr_amp=ampd
    else:
    
        if f_ini < f0amp:

            f1 = f0amp
            f3 = wfn.f_peak(m1,m2,chi1,chi2)
            f2 = (f1 + f3)/2.

            inspiral_amp = ampd + ampTH

            amp1interp = interp1d(f,inspiral_amp)

            v1 =  amp1interp(f1) 
            v3 =  ampdinterp(f3) 
            v2 =  ampdinterp(f2) 

            aprime1 = urel.dydx(f,inspiral_amp)
            aprime1interp = interp1d(f,aprime1)

            aprimed = urel.dydx(f,ampd)
            aprimedinterp = interp1d(f,aprimed)

            d1 =  aprime1interp(f1) 
            d3 =  aprimedinterp(f3) 

            A0 = wfn.A0(m1,m2,DL) 

            a = f1**(-7./6.)
            b = f2**(-7./6.)
            c = f3**(-7./6.)
            d = f1**(-13./6.)/6.
            e = f3**(-13./6.)/6.

            eq1 = [1.,f1,f1**2,f1**3,f1**4]
            eq1 = [x*(A0*a) for x in eq1]

            eq2 = [1.,f2,f2**2,f2**3,f2**4]
            eq2 = [x*(A0*b) for x in eq2]

            eq3 = [1.,f3,f3**2,f3**3,f3**4]
            eq3 = [x*(A0*c) for x in eq3]

            eq4 = [-7.,-f1,5*f1**2,11*f1**3,17*f1**4]
            eq4 = [x*(A0*d) for x in eq4]

            eq5 = [-7.,-f3,5*f3**2,11*f3**3,17*f3**4]
            eq5 = [x*(A0*e) for x in eq5]

            coeff = np.array([eq1, eq2, eq3, eq4, eq5])
            val = np.array([v1,v2,v3,d1,d3])

            sol = np.linalg.solve(coeff, val)

            delta0 = sol[0]
            delta1 = sol[1]
            delta2 = sol[2]
            delta3 = sol[3]
            delta4 = sol[4]


            amp_int = A0*(f**(-7./6.))*(delta0 + delta1*f + delta2*f**2 + delta3*f**3 + delta4*f**4)

            theta1plus, theta1minus = mfn.theta_pm(f,f1)
            theta2plus, theta2minus = mfn.theta_pm(f,f3)

            imr_amp = inspiral_amp*theta1minus + theta1plus*amp_int*theta2minus + theta2plus*ampd


        else: imr_amp = ampd
    
        
    ## phase model ----------------------
    
    phasedplus = -np.unwrap(np.angle(hplusD))
    if phase_corr == False: imr_phase = phasedplus
    else:
        phaseDinterpp = interp1d(f*M,phasedplus)

        sigma1 = mfn.Lambda(eta,chiPN,*lambdasigma1)
        sigma2 = mfn.Lambda(eta,chiPN,*lambdasigma2)
        sigma3 = mfn.Lambda(eta,chiPN,*lambdasigma3)
        sigma4 = mfn.Lambda(eta,chiPN,*lambdasigma4)

        aug_phase = mfn.aug_phase(f,m1,m2,sigma1,sigma2,sigma3,sigma4)
        inspiral_phase = phase_htf2 + aug_phase

        ###### C1 continuity, continuity of phase and its derivative ------------------------

        if M*f_ini<Mf2phase:

            phasedprime = urel.dydx(M*f,phasedplus)
            inspiral_phaseprime = urel.dydx(M*f,inspiral_phase)

            phasedprimeinterpp = interp1d(M*f,phasedprime)
            inspiral_phaseprimeinterpp = interp1d(M*f,inspiral_phaseprime)

            tc1 = phasedprimeinterpp(Mf2phase) - inspiral_phaseprimeinterpp(Mf2phase)

            inspiral_phase = inspiral_phase + M*f*tc1

            phaseinspinterpp = interp1d(f*M,inspiral_phase)
            phaseDinterpp = interp1d(f*M,phasedplus)

            sigma0 = phaseDinterpp(Mf2phase)-phaseinspinterpp(Mf2phase)

            inspiral_phase = inspiral_phase + sigma0

            f1 = Mf2phase/M

            thetaplus, thetaminus = mfn.theta_pm(f,f1)

            imr_phase = inspiral_phase*thetaminus + phasedplus*thetaplus


        else: imr_phase = phasedplus

    return indexini, f, imr_amp, imr_phase

def get_imrphenomd_horizon_fd(f_lower=None,f_final=None,delta_f=None,chi1=0,chi2=0,DL=200.,tc=0,phic=0,iota=0,m1=10,m2=10,
                Mf2amp=0.014,Mf2phase=0.018,amp_corr=False,phase_corr=True):
        
    Ms = (m1+m2)
    M = Ms*urel.MTsun
    
    if delta_f is None: raise Exception('Specify delta_f')
    if f_lower is None: f_lower = 0.0035/M
    if f_final is None: 
        f_final = 0.3/M
    
    indexini, f, amp, phase = amp_phase_PhenomD_Horizon(m1,m2,chi1,chi2,DL,tc,phic,iota,
                            delta_f=delta_f,f_ini=f_lower,f_final=f_final,
                            Mf2amp=Mf2amp,Mf2phase=Mf2phase,amp_corr=amp_corr,phase_corr=phase_corr)                            
    
    phase += 2*np.pi*f*tc + phic
    
    hptilde = 0.5*(1+np.cos(iota)**2)*amp*np.exp(-1j*phase)
    hctilde = -1j*np.cos(iota)*amp*np.exp(-1j*phase)
    
    xpatch = np.zeros(indexini)
     
    hptilde2 = np.concatenate((xpatch,hptilde))
    hctilde2 = np.concatenate((xpatch,hctilde))
    
       
    hptildepy = types.FrequencySeries(hptilde2,delta_f=delta_f)
    hctildepy = types.FrequencySeries(hctilde2,delta_f=delta_f)
    
    
    return hptildepy, hctildepy


def get_imrphenomd_heated_fd(f_lower=None,f_final=None,delta_f=None,chi1=0,chi2=0,DL=200.,tc=0,phic=0,iota=0,m1=10,m2=10,H=1.,
                Mf2amp=0.014,Mf2phase=0.018,amp_corr=False,phase_corr=True,Mf_transition1=0.022,Mf_transition2=0.032):
        
    Ms = (m1+m2)
    M = Ms*urel.MTsun
    
    if delta_f is None: raise Exception('Specify delta_f')
    if f_lower is None: f_lower = 0.0035/M
    if f_final is None: 
        f_final = 0.3/M

    ## this is added because the approximant does not support spins right now
    if np.abs(chi1)>1e-7 or np.abs(chi2)>1e-7: raise Exception('nonzero spins are not supported at the moment.')
    #----------------------------------------------------------------------

    indexini, f, amp, phase = amp_phase_PhenomD_Horizon(m1,m2,chi1,chi2,DL,tc,phic,iota,
                            delta_f=delta_f,f_ini=f_lower,f_final=f_final,
                            Mf2amp=Mf2amp,Mf2phase=Mf2phase,amp_corr=amp_corr,phase_corr=phase_corr)                            
    
    
    # imr_phase_TH_a = nr_heat.imr_tidal_heating_approximant(f,m1,m2,Mf_transition1=Mf_transition1,Mf_transition2=Mf_transition2)
    imr_phase_TH_a = nr_heat.imr_tidal_heating_approximant2(f,m1,m2)
    merger_f = wfn.Mf_peak_td_fit(m1,m2)/M
    # imr_phase_TH *= urel.planck_taper_window(f,t3=0.04/M,t4=merger_f,only_right=True)
    # imr_phase_TH *= urel.planck_taper_window(f,t3=merger_f,t4=1.2*merger_f,only_right=True)
    w = urel.planck_taper_window(f,t1=1.15*merger_f,t2=1.35*merger_f,only_left=True)
    inspiral_phase=nr_heat.Psi_1(f,m1,m2)
    imr_phase_TH = (1.-w)*imr_phase_TH_a+w*inspiral_phase

    phase += (H-1)*imr_phase_TH + 2*np.pi*f*tc + phic
    
    hptilde = 0.5*(1+np.cos(iota)**2)*amp*np.exp(-1j*phase)
    hctilde = -1j*np.cos(iota)*amp*np.exp(-1j*phase)

    hptilde *= urel.planck_taper_window(hptilde.sample_frequencies,t3=merger_f,t4=1.2*merger_f,only_right=True)
    hctilde *= urel.planck_taper_window(hctilde.sample_frequencies,t3=merger_f,t4=1.2*merger_f,only_right=True)
    
    xpatch = np.zeros(indexini)
     
    hptilde2 = np.concatenate((xpatch,hptilde))
    hctilde2 = np.concatenate((xpatch,hctilde))
    
       
    hptildepy = types.FrequencySeries(hptilde2,delta_f=delta_f)
    hctildepy = types.FrequencySeries(hctilde2,delta_f=delta_f)
    
    
    return hptildepy, hctildepy
